import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load atlas texture
  const atlasTexture = ctx.textureLoader.load(config.assets.imageUrl);
  atlasTexture.colorSpace = THREE.SRGBColorSpace;

  // Atlas region specification from config (pixel coordinates)
  const atlasRegionX = 0;
  const atlasRegionY = 0;
  const atlasRegionWidth = 512;
  const atlasRegionHeight = 320;

  // Assuming 512×512 atlas (standard size matching region width)
  const atlasSize = 512;

  // Compute normalized UV bounds for this region
  const uvMinX = atlasRegionX / atlasSize;
  const uvMaxX = (atlasRegionX + atlasRegionWidth) / atlasSize;
  const uvMinY = atlasRegionY / atlasSize;
  const uvMaxY = (atlasRegionY + atlasRegionHeight) / atlasSize;

  // Create plane geometry with aspect ratio matching atlas region
  const aspectRatio = atlasRegionWidth / atlasRegionHeight;
  const planeWidth = 2.0;
  const planeHeight = planeWidth / aspectRatio;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Remap UVs to sample the correct atlas region
  const uvAttribute = geometry.attributes.uv;
  for (let i = 0; i < uvAttribute.count; i++) {
    const baseU = uvAttribute.getX(i);
    const baseV = uvAttribute.getY(i);

    const mappedU = uvMinX + baseU * (uvMaxX - uvMinX);
    const mappedV = uvMinY + baseV * (uvMaxY - uvMinY);

    uvAttribute.setXY(i, mappedU, mappedV);
  }
  uvAttribute.needsUpdate = true;

  // Create material with TSL texture node
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    toneMapped: false,
    side: THREE.DoubleSide
  });
  material.colorNode = texture(atlasTexture);

  // Create mesh and add to group
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    atlasTexture.dispose();
  };

  group.userData.handlers = {};

  return group;
}
